import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { db } from "./db";
import { ovh, ovhApi, ovhConfigured } from "./ovh";
import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
import { getSettingInt } from "./settings";

const execFileP = promisify(execFile);

/**
 * Is this address already the target of a live DNAT rule on this host? Some
 * infrastructure (the shared-hosting node, VM 200) reaches its dedicated IP
 * entirely through a whole-IP DNAT rule to an internal address — it has no OVH
 * Virtual MAC at all, so the MAC-based check above cannot see it. A real
 * incident: this exact IP was one query away from being handed to a game
 * server because "no Virtual MAC bound" was mistaken for "free" — it was
 * actively carrying production hosting traffic via `iptables -t nat`. Treat
 * any address with a live DNAT target as claimed, unconditionally.
 */
async function hasLiveDnatRule(address: string): Promise<boolean> {
  try {
    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
  } catch {
    // iptables unreadable (permissions, not present, sandboxed test env) — fail
    // closed is wrong here (it would make every sync a no-op); fail to "not
    // claimed by this specific check" and rely on the Virtual MAC check plus
    // the existing DB row remaining authoritative for anything already tracked.
    return false;
  }
}

const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
/**
 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
 */
export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);

/**
 * The monthly dedicated-IP surcharge actually charged, from the admin setting
 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
 * every order/renewal/display path so they can never disagree.
 *
 * NORMALISED to a non-negative whole number of cents, exactly as
 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
 * row — every one of which is integer cents. A fractional setting produced a
 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
 * to it; a negative one silently discounted the plan.
 */
export async function dedicatedIpMonthlyCents(): Promise<number> {
  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
  return Math.max(0, Math.round(v));
}
/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);

/** OVH failover gateway = the host's /24 gateway (…​.254). */
export function ovhGateway(): string {
  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
  const parts = ip.split(".");
  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
}

/**
 * Pull additional/failover IPv4 addresses routed to our server from OVH and
 * upsert them into the pool. The host's own primary IP is never poolable.
 */
export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
  if (SANDBOX) return { imported: 0, total: 0 };
  if (!ovhConfigured()) return { imported: 0, total: 0 };
  const primary = process.env.PUBLIC_IP;
  const blocks: string[] = await ovhApi.ips();
  let imported = 0;
  for (const block of blocks) {
    if (block.includes(":")) continue; // IPv6 handled separately
    let info: any;
    try {
      info = await ovhApi.ipInfo(block);
    } catch {
      continue;
    }
    if (info?.routedTo?.serviceName !== SERVER) continue;
    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
    // A /32 block is a single usable IP == the block minus the mask.
    const address = block.split("/")[0];
    if (address === primary) continue;
    const existing = await db.dedicatedIp.findUnique({ where: { address } });
    if (!existing) {
      // An IP that already has a Virtual MAC bound to it on OVH's side is already
      // in active use by SOME VM — possibly one this app never created a Server
      // row for (e.g. internal infrastructure provisioned directly via the OVH
      // API, like the cold-email relay). A genuinely free IP has no bound MAC
      // yet. Importing it as FREE anyway let a real customer server collide with
      // an unrelated VM's network identity — never assign an IP that's already
      // claimed at the network layer, regardless of whether our DB knows about it.
      if (await findVirtualMacForIp(address)) continue;
      if (await hasLiveDnatRule(address)) continue;
      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
      imported++;
    }
  }
  const total = await db.dedicatedIp.count();
  return { imported, total };
}

export async function freeCount(): Promise<number> {
  return db.dedicatedIp.count({ where: { status: "FREE" } });
}

/** Find the OVH Virtual MAC currently bound to an IP, if any. */
async function findVirtualMacForIp(address: string): Promise<string | null> {
  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
  for (const m of macs) {
    const ips: string[] = await ovh(
      "GET",
      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
    ).catch(() => []);
    if (ips.includes(address)) return m;
  }
  return null;
}

/**
 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
 * Returns the address + virtualMac + gateway, or null if none available.
 */
export async function allocateDedicatedIp(
  serverId: string,
  vmid: number
): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
  if (SANDBOX) {
    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
  }
  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
  }
  if (!ovhConfigured()) return null;
  // Atomically claim a FREE ip
  const claim = await db.$transaction(async (tx) => {
    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
    if (!ip) return null;
    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
    return ip;
  });
  if (!claim) return null;

  try {
    // Reuse an existing vMAC for this IP if one is already bound; else create one.
    let mac = await findVirtualMacForIp(claim.address);
    if (!mac) {
      // Creation is asynchronous (returns a task) — kick it off then poll.
      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
      for (let i = 0; i < 40 && !mac; i++) {
        await new Promise((r) => setTimeout(r, 3000));
        mac = await findVirtualMacForIp(claim.address);
      }
    }
    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
  } catch (e) {
    // Roll the claim back to FREE on failure
    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
    throw e;
  }
}

/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
export async function releaseDedicatedIp(serverId: string): Promise<void> {
  if (SANDBOX) return;
  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
  if (!ip) return;
  if (ovhConfigured() && ip.virtualMac) {
    try {
      // Remove the IP from the vMAC, then delete the vMAC.
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
    } catch {
      /* best-effort */
    }
  }
  await db.dedicatedIp.update({
    where: { id: ip.id },
    data: { status: "FREE", serverId: null, virtualMac: null },
  });
}

/** Set reverse DNS (PTR) for a dedicated IP. */
export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
  if (!ovhConfigured()) return;
  await ovhApi.setReverse(`${address}/32`, address, reverse);
  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
}

enum InvoiceStatus {
  OPEN
  PAID
  VOID
  REFUNDED
}

model Invoice {
  id                String             @id @default(cuid())
  number            Int                @unique @default(autoincrement())
  userId            String
  user              User               @relation(fields: [userId], references: [id], onDelete: Cascade)
  amountCents       Int
  taxCents          Int                @default(0)
  // The VAT/GST rate (percent) actually applied to this invoice's net, and the
  // destination country it was charged for. Recorded at creation from the customer's
  // billing country (lib/tax.ts) so the document states the rate and jurisdiction the
  // tax was collected under — required once tax is genuinely charged. 0 / null on a
  // no-tax invoice (unknown country, reverse charge, or a wallet top-up, which is
  // never a taxable sale).
  taxRatePercent    Float              @default(0)
  taxCountry        String?
  status            InvoiceStatus      @default(OPEN)
  // How much of this invoice has already been refunded. Refunds used to be bound
  // to nothing: `refundPayment` took only (userId, amount) and picked its Stripe
  // target as "most recent top-up, any amount" — so refunding a $24 March invoice
  // issued $24 against the customer's $200 July top-up, the invoice stayed PAID,
  // and the next admin refunded it again. Tracking it here lets the action refuse
  // to exceed the original and mark the invoice REFUNDED.
  refundedCents     Int                @default(0)
  description       String
  lineItems         Json // [{ description, qty, unitCents, amountCents }]
  periodStart       DateTime?
  periodEnd         DateTime?
  paidAt            DateTime?
  // Snapshot of the card used to pay this invoice, captured at the PAID transition
  // so the record survives the customer later swapping or removing their card.
  // Nullable + additive: invoices issued before this existed fall back to the
  // user's current card fields at render time.
  paidBrand         String? // card brand snapshot at time paid (e.g. "visa")
  paidLast4         String? // card last4 snapshot at time paid
  createdAt         DateTime           @default(now())
  // Optional KOL/agency partner commission accrued against this invoice. The FK
  // (with its UNIQUE) lives on PartnerCommission, so this back-relation adds no
  // column to the invoices table — additive/safe for `prisma db push`.
  partnerCommission PartnerCommission?
}

// ---- Growth: coupons / promo codes ----
