import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * Structural guards over the ADMIN / STAFF server actions.
 *
 * `test/customer-actions-guards.test.ts` proves that every export of the
 * CUSTOMER-facing action modules identifies its caller — but its file list stops
 * at the customer surface, so the admin-only modules (refunds, staff roles, node
 * lifecycle, abuse, gift codes, mass mail…) had no equivalent net. Every export
 * of a `"use server"` file is a public network endpoint reachable by curl, so an
 * admin action whose `requireAdmin()`/`requireArea()` was dropped in a refactor
 * would be a privilege hole with nothing to catch it. This is that net.
 *
 * A guard here is not merely "authenticates" — it must be the RIGHT authority.
 * The area/role each module enforces is asserted separately (see EXPECTED below),
 * so a module cannot pass by swapping `requireAdmin` for a bare `requireUser`.
 *
 * Source is comment-stripped first: this repo documents its incidents in the code
 * and a raw grep matches the note, not the call. See test/_source-tools.ts.
 */

const LIB = join(import.meta.dirname, "..", "lib");
const source = (file: string) => stripComments(readFileSync(join(LIB, file), "utf8"));

function exportedActions(src: string): string[] {
  return [...src.matchAll(/export\s+async\s+function\s+([A-Za-z0-9_$]+)\s*\(/g)].map((m) => m[1]);
}

/** Brace-matched body of an exported async function (skips return-type braces). */
function bodyOf(src: string, name: string): string {
  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
  assert.ok(decl, `expected an exported action named ${name}`);
  let i = src.indexOf("(", decl.index);
  let parens = 0;
  let quote: string | null = null;
  for (; i < src.length; i++) {
    const c = src[i];
    if (quote) {
      if (c === "\\") i++;
      else if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") quote = c;
    else if (c === "(") parens++;
    else if (c === ")" && --parens === 0) break;
  }
  let angles = 0;
  for (i++; i < src.length; i++) {
    const c = src[i];
    if (c === "<") angles++;
    else if (c === ">") angles = Math.max(0, angles - 1);
    else if (c === "{" && angles === 0) break;
  }
  const start = i;
  let depth = 0;
  quote = null;

const AUTH_MARKERS = [
  "requireAdmin(",
  "requireArea(",
  "requireStaff(",
  "requireUser(",
  "realUser(",
  "ownedServer(",
];

/**
 * Admin/staff action modules behind the admin portal, and the guard each of their
 * privileged exports is expected to reach for. Files not in
 * customer-actions-guards' list. Every listed module carries `"use server"`.
 */
const ADMIN_ACTION_FILES = [
  "actions-admin-billing.ts",
  "actions-staff.ts",
  "actions-nodes.ts",
  "actions-abuse.ts",
  "actions-blog.ts",
  "actions-chat.ts",
  "actions-testimonials.ts",
  "actions-gift.ts",
  "actions-games.ts",
  "actions-improvements.ts",
  "actions-email-templates.ts",
  "actions-mail-admin.ts",
  "actions-newsletter-campaign.ts",
  "actions-ovh.ts",
  "actions-billing.ts",
  "actions-feedback.ts",
  "actions-account.ts",
] as const;

/**
 * Exports that are SUPPOSED to answer without a require* guard, each with the
 * reason. `requestPasswordReset`/`resetPassword` are the public forgot-password
 * flow (token-gated, like register/login). `stopImpersonating` only clears the
 * CALLER's own impersonation cookie — it removes privilege, never grants it.
 */
const INTENTIONALLY_UNGUARDED = new Set([
  "actions-account.ts:requestPasswordReset",
  "actions-account.ts:resetPassword",
  "actions-account.ts:stopImpersonating",
]);

test("every admin/staff server action identifies its caller inside the function", () => {
  const unguarded: string[] = [];
  for (const file of ADMIN_ACTION_FILES) {
    const src = source(file);
    assert.ok(src.includes('"use server"'), `${file} should declare "use server"`);
    for (const name of exportedActions(src)) {
      const key = `${file}:${name}`;
      if (INTENTIONALLY_UNGUARDED.has(key)) continue;
      if (!AUTH_MARKERS.some((m) => bodyOf(src, name).includes(m))) unguarded.push(key);
    }
  }
  assert.deepEqual(
    unguarded,
    [],
    "these admin endpoints are network-reachable with no caller check inside the function",
  );
});

/**
 * The privileged writes must reach for STAFF authority (requireAdmin / requireArea
 * / requireStaff), never merely `requireUser`. A customer-facing export in the same
 * module (e.g. gift-code redemption, feedback submission, a profile edit) legitimately
 * uses requireUser — those are allowlisted by name so the assertion stays sharp.
 */
const CUSTOMER_FACING_IN_ADMIN_MODULE = new Set([
  "actions-gift.ts:redeemGiftCode",
  "actions-feedback.ts:submitFeedback",
  // actions-account.ts is mostly the customer's own account controls.
  "actions-account.ts:updateProfile",
  "actions-account.ts:changePassword",
  "actions-account.ts:addSshKey",
  "actions-account.ts:deleteSshKey",
  "actions-account.ts:createProject",
  "actions-account.ts:deleteProject",
  "actions-account.ts:assignServerProject",
  "actions-account.ts:markNotificationsRead",
  // Customer signs out their OWN other sessions (scoped to where:{id:user.id}).
  "actions-account.ts:signOutOtherSessions",
]);

const STAFF_MARKERS = ["requireAdmin(", "requireArea(", "requireStaff("];

test("privileged admin writes reach for staff authority, not bare requireUser", () => {
  const weak: string[] = [];
  for (const file of ADMIN_ACTION_FILES) {
    const src = source(file);
    for (const name of exportedActions(src)) {
      const key = `${file}:${name}`;
      if (INTENTIONALLY_UNGUARDED.has(key) || CUSTOMER_FACING_IN_ADMIN_MODULE.has(key)) continue;
      const body = bodyOf(src, name);
      if (!STAFF_MARKERS.some((m) => body.includes(m))) weak.push(key);
    }
  }
  assert.deepEqual(
    weak,
    [],
    "these admin actions authenticate but do not enforce a STAFF role — a customer could reach them",
  );
});

