/**
 * Pure helpers for the admin Accounting section (v1 of real revenue/cost
 * tracking). Deliberately free of any DB/server import so the aggregation math
 * is unit-testable without a database — see test/accounting-calc.test.ts.
 *
 * "use server" action code (lib/actions-accounting.ts) and the dashboard page
 * (app/admin/accounting/page.tsx) fetch rows from Prisma and hand plain data
 * into these functions; nothing here talks to `db` directly.
 */

/** The fixed expense-category set. Enforced here (not a Postgres enum — see the
 * Expense model doc-comment in prisma/schema.prisma) and re-used by the Zod
 * schema in lib/actions-accounting.ts and by the admin UI's category picker. */
export const EXPENSE_CATEGORIES = [
  "INFRASTRUCTURE",
  "SOFTWARE",
  "PAYMENT_PROCESSING",
  "MARKETING",
  "LEGAL",
  "PAYROLL",
  "OTHER",
] as const;
export type ExpenseCategory = (typeof EXPENSE_CATEGORIES)[number];

export function isExpenseCategory(v: string): v is ExpenseCategory {
  return (EXPENSE_CATEGORIES as readonly string[]).includes(v);
}

/** Human label for a category value, for the UI. */
export const EXPENSE_CATEGORY_LABELS: Record<ExpenseCategory, string> = {
  INFRASTRUCTURE: "Infrastructure",
  SOFTWARE: "Software",
  PAYMENT_PROCESSING: "Payment processing",
  MARKETING: "Marketing",
  LEGAL: "Legal",
  PAYROLL: "Payroll",
  OTHER: "Other",
};

export const EXPENSE_INTERVALS = ["MONTHLY", "YEARLY"] as const;
export type ExpenseInterval = (typeof EXPENSE_INTERVALS)[number];

export function isExpenseInterval(v: string): v is ExpenseInterval {
  return (EXPENSE_INTERVALS as readonly string[]).includes(v);
}

/** Minimal shape of an Expense row needed for the aggregation helpers below. */
export type ExpenseLike = {
  amountCents: number;
  category: string;
  occurredAt: Date;
  isRecurring: boolean;
  recurringInterval: string | null;
};

/** A synthetic, non-manually-entered expense line pulled from live platform
 * data (e.g. the OVH dedicated-IP pool cost). Rendered in the dashboard/trend
 * alongside real `Expense` rows but never written to the table. */
export type AutoExpenseLine = {
  key: string;
  label: string;
  amountCents: number;
  category: ExpenseCategory;
};

/** "YYYY-MM" for a date, in UTC (mirrors monthKey() in app/admin/analytics/page.tsx). */
export function monthKey(d: Date): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

/** The `count` most recent calendar months (UTC), oldest first, as "YYYY-MM" keys. */
export function trailingMonthKeys(count: number, now: Date = new Date()): string[] {
  const keys: string[] = [];
  for (let i = count - 1; i >= 0; i--) {
    keys.push(monthKey(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1))));
  }
  return keys;
}

/** Sum of `amountCents` for expenses whose `occurredAt` falls in calendar month `key`. */
export function expensesInMonth(expenses: ExpenseLike[], key: string): number {
  return expenses.filter((e) => monthKey(e.occurredAt) === key).reduce((n, e) => n + e.amountCents, 0);
}

/** Sum of `amountCents` across every category. */
export function totalCents(expenses: ExpenseLike[]): number {
  return expenses.reduce((n, e) => n + e.amountCents, 0);
}

/** Sum of `amountCents` grouped by category, including every category (0 when unused). */
export function totalsByCategory(expenses: ExpenseLike[]): Record<ExpenseCategory, number> {
  const totals = Object.fromEntries(EXPENSE_CATEGORIES.map((c) => [c, 0])) as Record<ExpenseCategory, number>;
  for (const e of expenses) {
    if (isExpenseCategory(e.category)) totals[e.category] += e.amountCents;
  }
  return totals;
}

/**
 * A month-by-month revenue/expense/net trend series, oldest month first.
 * `revenueByMonth`/`expensesByMonth` are pre-aggregated maps of "YYYY-MM" ->
 * cents (the caller decides how revenue is sourced — see the dashboard page,
 * which uses the platform's existing REVENUE_WHERE wallet-ledger definition).
 */
export function buildTrend(
  monthKeys: string[],
  revenueByMonth: Map<string, number>,
  expensesByMonth: Map<string, number>
): { month: string; revenueCents: number; expenseCents: number; netCents: number }[] {
  return monthKeys.map((month) => {
    const revenueCents = revenueByMonth.get(month) ?? 0;
    const expenseCents = expensesByMonth.get(month) ?? 0;
    return { month, revenueCents, expenseCents, netCents: revenueCents - expenseCents };
  });
}

/**
 * Project a recurring expense's due dates forward, up to `monthsAhead` full
 * calendar months from `from`. A MONTHLY expense contributes once per month it
 * spans; a YEARLY one only contributes in the month(s) its `nextDueAt` actually
 * falls in. Returns cents due per "YYYY-MM" key — used for the "next N months"
 * projected-recurring view. Deliberately simple (v1): it does not auto-create
 * Expense rows or roll `nextDueAt` forward — see the "v2" note in the module
 * doc-comment of lib/actions-accounting.ts.
 */
export function projectRecurring(
  expenses: ExpenseLike[],
  monthsAhead: number,
  from: Date = new Date()
): Map<string, number> {
  const projected = new Map<string, number>();
  const startKeys: string[] = [];
  for (let i = 0; i < monthsAhead; i++) {
    startKeys.push(monthKey(new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth() + i, 1))));
  }
  for (const key of startKeys) projected.set(key, projected.get(key) ?? 0);

  for (const e of expenses) {
    if (!e.isRecurring) continue;
    if (e.recurringInterval === "MONTHLY") {
      for (const key of startKeys) {
        projected.set(key, (projected.get(key) ?? 0) + e.amountCents);
      }
    } else if (e.recurringInterval === "YEARLY") {
      // Falls in exactly the projected months that share its occurrence month,
      // across whichever year(s) fall inside the window.
      const anchorMonth = e.occurredAt.getUTCMonth();
      for (let i = 0; i < monthsAhead; i++) {
        const d = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth() + i, 1));
        if (d.getUTCMonth() === anchorMonth) {
          const key = monthKey(d);
          projected.set(key, (projected.get(key) ?? 0) + e.amountCents);
        }
      }
    }
  }
  return projected;
}

/** Merge auto-pulled expense lines' total into a manually-entered expense total. */
export function totalWithAuto(manualCents: number, autoLines: AutoExpenseLine[]): number {
  return manualCents + autoLines.reduce((n, l) => n + l.amountCents, 0);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  monthKey,
  trailingMonthKeys,
  expensesInMonth,
  totalCents,
  totalsByCategory,
  buildTrend,
  projectRecurring,
  totalWithAuto,
  isExpenseCategory,
  isExpenseInterval,
  type ExpenseLike,
} from "../lib/accounting.ts";

test("monthKey formats UTC year-month", () => {
  assert.equal(monthKey(new Date(Date.UTC(2026, 0, 15))), "2026-01");
  assert.equal(monthKey(new Date(Date.UTC(2026, 11, 1))), "2026-12");
});

test("trailingMonthKeys returns N months ending at `now`, oldest first", () => {
  const now = new Date(Date.UTC(2026, 2, 10)); // March 2026
  assert.deepEqual(trailingMonthKeys(3, now), ["2026-01", "2026-02", "2026-03"]);
  assert.deepEqual(trailingMonthKeys(1, now), ["2026-03"]);
});

test("trailingMonthKeys handles year rollover", () => {
  const now = new Date(Date.UTC(2026, 1, 1)); // Feb 2026
  assert.deepEqual(trailingMonthKeys(4, now), ["2025-11", "2025-12", "2026-01", "2026-02"]);
});

function expense(partial: Partial<ExpenseLike>): ExpenseLike {
  return {
    amountCents: 1000,
    category: "OTHER",
    occurredAt: new Date(Date.UTC(2026, 0, 1)),
    isRecurring: false,
    recurringInterval: null,
    ...partial,
  };
}

test("expensesInMonth sums only rows occurring in that month", () => {
  const rows = [
    expense({ amountCents: 500, occurredAt: new Date(Date.UTC(2026, 0, 5)) }),
    expense({ amountCents: 700, occurredAt: new Date(Date.UTC(2026, 0, 20)) }),
    expense({ amountCents: 999, occurredAt: new Date(Date.UTC(2026, 1, 1)) }), // Feb, excluded
  ];
  assert.equal(expensesInMonth(rows, "2026-01"), 1200);
  assert.equal(expensesInMonth(rows, "2026-02"), 999);
  assert.equal(expensesInMonth(rows, "2026-03"), 0);
});

test("totalCents sums every row regardless of category", () => {
  const rows = [expense({ amountCents: 100 }), expense({ amountCents: 250 }), expense({ amountCents: -50 })];
  assert.equal(totalCents(rows), 300);
});

test("totalsByCategory buckets by category and zero-fills unused ones", () => {
  const rows = [
    expense({ amountCents: 1000, category: "INFRASTRUCTURE" }),
    expense({ amountCents: 2000, category: "INFRASTRUCTURE" }),
    expense({ amountCents: 500, category: "SOFTWARE" }),
  ];
  const totals = totalsByCategory(rows);
  assert.equal(totals.INFRASTRUCTURE, 3000);
  assert.equal(totals.SOFTWARE, 500);
  assert.equal(totals.MARKETING, 0);
  assert.equal(totals.OTHER, 0);
});

test("totalsByCategory ignores a row with an unrecognized category value", () => {
  const rows = [expense({ amountCents: 1000, category: "NOT_A_REAL_CATEGORY" })];
  const totals = totalsByCategory(rows);
  assert.equal(Object.values(totals).reduce((a, b) => a + b, 0), 0);
});

test("buildTrend pairs revenue/expense maps into a per-month net series", () => {
  const revenue = new Map([
    ["2026-01", 10000],
    ["2026-02", 12000],
  ]);
  const expenses = new Map([["2026-01", 4000]]); // Feb intentionally missing -> 0
  const trend = buildTrend(["2026-01", "2026-02"], revenue, expenses);
  assert.deepEqual(trend, [
    { month: "2026-01", revenueCents: 10000, expenseCents: 4000, netCents: 6000 },
    { month: "2026-02", revenueCents: 12000, expenseCents: 0, netCents: 12000 },
  ]);
});

test("projectRecurring: a MONTHLY expense contributes to every projected month", () => {
  const rows = [
    expense({ amountCents: 500, isRecurring: true, recurringInterval: "MONTHLY", occurredAt: new Date(Date.UTC(2025, 5, 1)) }),
  ];
  const from = new Date(Date.UTC(2026, 0, 1)); // Jan 2026
  const projected = projectRecurring(rows, 3, from);
  assert.deepEqual([...projected.entries()], [
    ["2026-01", 500],
    ["2026-02", 500],
    ["2026-03", 500],
  ]);
});

test("projectRecurring: a YEARLY expense only lands in its anchor month", () => {
  const rows = [
    // Anchored in March (month index 2).
    expense({ amountCents: 12000, isRecurring: true, recurringInterval: "YEARLY", occurredAt: new Date(Date.UTC(2025, 2, 15)) }),
  ];
  const from = new Date(Date.UTC(2026, 0, 1)); // Jan 2026, project 6 months (Jan..Jun)
  const projected = projectRecurring(rows, 6, from);
  assert.equal(projected.get("2026-01"), 0);
  assert.equal(projected.get("2026-02"), 0);
  assert.equal(projected.get("2026-03"), 12000);
  assert.equal(projected.get("2026-04"), 0);
});

test("projectRecurring ignores non-recurring expenses entirely", () => {
  const rows = [expense({ amountCents: 999, isRecurring: false, recurringInterval: null })];
  const projected = projectRecurring(rows, 2, new Date(Date.UTC(2026, 0, 1)));
  assert.equal([...projected.values()].reduce((a, b) => a + b, 0), 0);
});

test("totalWithAuto adds manually-entered total to every auto-pulled line", () => {
  const auto = [
    { key: "ovh-ip-pool", label: "OVH dedicated IP pool", amountCents: 1195, category: "INFRASTRUCTURE" as const },
  ];
  assert.equal(totalWithAuto(5000, auto), 6195);
  assert.equal(totalWithAuto(0, []), 0);
});

test("isExpenseCategory / isExpenseInterval reject unknown values", () => {
  assert.equal(isExpenseCategory("INFRASTRUCTURE"), true);
  assert.equal(isExpenseCategory("MADE_UP"), false);
  assert.equal(isExpenseInterval("MONTHLY"), true);
  assert.equal(isExpenseInterval("WEEKLY"), false);
});

