"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireArea } from "./rbac";
import { EXPENSE_CATEGORIES, EXPENSE_INTERVALS } from "./accounting";

/**
 * Admin server actions for the Accounting section (v1 of real revenue/cost
 * tracking, /admin/accounting*). CRUD over the `Expense` table — manually
 * entered costs the platform doesn't already track anywhere else (the
 * dashboard also merges in auto-pulled lines like the OVH dedicated-IP pool
 * cost, computed live in lib/dedicated-ip.ts, which never get an Expense row).
 *
 * Every export is gated by `requireArea("accounting")` (ADMIN-only, see
 * lib/rbac.ts) and writes an AuditLog row, matching the convention in
 * lib/actions-admin-billing.ts.
 *
 * v2 candidates deliberately NOT built here (see the PR/report for the
 * reasoning): an auto-generating recurring-expense sweep that rolls
 * `nextDueAt` forward and creates the next period's row automatically, live
 * Stripe processing-fee ingestion, and per-customer profitability.
 */

async function audit(userId: string, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

const dateOrUndefined = z
  .string()
  .optional()
  .transform((v) => (v ? new Date(v) : undefined))
  .refine((d) => d === undefined || !Number.isNaN(d.getTime()), "Invalid date");

const expenseSchema = z.object({
  description: z.string().trim().min(1, "Description is required.").max(200),
  amount: z.coerce.number().positive("Amount must be greater than $0.").max(1_000_000),
  category: z.enum(EXPENSE_CATEGORIES),
  vendor: z.string().trim().max(120).optional(),
  notes: z.string().trim().max(2000).optional(),
  occurredAt: dateOrUndefined,
  isRecurring: z.coerce.boolean().optional(),
  recurringInterval: z.enum(EXPENSE_INTERVALS).optional(),
  nextDueAt: dateOrUndefined,
});

type ActionResult = { error?: string; ok?: boolean };

function emptyToUndefined(v: FormDataEntryValue | null): string | undefined {
  const s = String(v ?? "").trim();
  return s === "" ? undefined : s;
}

/** Create a manually-entered expense line. */
export async function createExpense(_prev: unknown, formData: FormData): Promise<ActionResult> {
  const admin = await requireArea("accounting");

  const isRecurring = formData.get("isRecurring") === "on" || formData.get("isRecurring") === "true";
  const parsed = expenseSchema.safeParse({
    description: formData.get("description"),
    amount: formData.get("amount"),
    category: formData.get("category"),
    vendor: emptyToUndefined(formData.get("vendor")),
    notes: emptyToUndefined(formData.get("notes")),
    occurredAt: emptyToUndefined(formData.get("occurredAt")),
    isRecurring,
    recurringInterval: emptyToUndefined(formData.get("recurringInterval")),
    nextDueAt: emptyToUndefined(formData.get("nextDueAt")),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid expense details." };
  }
  const d = parsed.data;
  if (d.isRecurring && !d.recurringInterval) {
    return { error: "Choose how often a recurring expense repeats." };
  }

  const amountCents = Math.round(d.amount * 100);
  await db.expense.create({
    data: {
      description: d.description,
      amountCents,
      category: d.category,
      vendor: d.vendor ?? null,
      notes: d.notes ?? null,
      occurredAt: d.occurredAt ?? new Date(),
      isRecurring: Boolean(d.isRecurring),
      recurringInterval: d.isRecurring ? (d.recurringInterval ?? null) : null,
      nextDueAt: d.isRecurring ? (d.nextDueAt ?? null) : null,
      createdById: admin.id,
    },
  });

  await audit(admin.id, "admin.expense_create", `${d.description} · $${d.amount.toFixed(2)} · ${d.category}`);
  revalidatePath("/admin/accounting");
  revalidatePath("/admin/accounting/expenses");
  return { ok: true };
}

/** Edit an existing expense. */
export async function updateExpense(_prev: unknown, formData: FormData): Promise<ActionResult> {
  const admin = await requireArea("accounting");
  const id = String(formData.get("id") ?? "");
  if (!id) return { error: "Missing expense id." };

  const existing = await db.expense.findUnique({ where: { id } });
  if (!existing) return { error: "Expense not found." };

  const isRecurring = formData.get("isRecurring") === "on" || formData.get("isRecurring") === "true";
  const parsed = expenseSchema.safeParse({
    description: formData.get("description"),
    amount: formData.get("amount"),
    category: formData.get("category"),
    vendor: emptyToUndefined(formData.get("vendor")),
    notes: emptyToUndefined(formData.get("notes")),
    occurredAt: emptyToUndefined(formData.get("occurredAt")),
    isRecurring,
    recurringInterval: emptyToUndefined(formData.get("recurringInterval")),
    nextDueAt: emptyToUndefined(formData.get("nextDueAt")),
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid expense details." };
  }
  const d = parsed.data;
  if (d.isRecurring && !d.recurringInterval) {
    return { error: "Choose how often a recurring expense repeats." };
  }

  const amountCents = Math.round(d.amount * 100);
  await db.expense.update({
    where: { id },
    data: {
      description: d.description,
      amountCents,
      category: d.category,
      vendor: d.vendor ?? null,
      notes: d.notes ?? null,
      occurredAt: d.occurredAt ?? existing.occurredAt,
      isRecurring: Boolean(d.isRecurring),
      recurringInterval: d.isRecurring ? (d.recurringInterval ?? null) : null,
      nextDueAt: d.isRecurring ? (d.nextDueAt ?? null) : null,
    },
  });

  await audit(admin.id, "admin.expense_update", `${id} · ${d.description} · $${d.amount.toFixed(2)}`);
  revalidatePath("/admin/accounting");
  revalidatePath("/admin/accounting/expenses");
  return { ok: true };
}

/** Delete an expense. */
export async function deleteExpense(id: string): Promise<void> {
  const admin = await requireArea("accounting");
  const existing = await db.expense.findUnique({ where: { id } });
  if (!existing) return;
  await db.expense.delete({ where: { id } });
  await audit(admin.id, "admin.expense_delete", `${existing.description} · $${(existing.amountCents / 100).toFixed(2)}`);
  revalidatePath("/admin/accounting");
  revalidatePath("/admin/accounting/expenses");
}

