"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import { createExpense, updateExpense, deleteExpense } from "@/lib/actions-accounting";
import { EXPENSE_CATEGORIES, EXPENSE_CATEGORY_LABELS, EXPENSE_INTERVALS, type ExpenseCategory } from "@/lib/accounting";

type ExpenseRow = {
  id: string;
  description: string;
  amountCents: number;
  category: string;
  vendor: string | null;
  notes: string | null;
  occurredAt: string; // ISO date, pre-serialized by the page
  isRecurring: boolean;
  recurringInterval: string | null;
  nextDueAt: string | null;
};

function toDateInputValue(iso: string): string {
  return iso.slice(0, 10);
}

/** Shared body of the create/edit form fields (everything except the submit row). */
function ExpenseFields({ defaults }: { defaults?: Partial<ExpenseRow> }) {
  const [isRecurring, setIsRecurring] = useState(defaults?.isRecurring ?? false);
  return (
    <>
      <div className="sm:col-span-2">
        <label className="label">Description</label>
        <input
          className="input"
          name="description"
          placeholder="e.g. Anthropic API usage"
          maxLength={200}
          defaultValue={defaults?.description}
          required
        />
      </div>
      <div>
        <label className="label">Amount (USD)</label>
        <input
          className="input"
          name="amount"
          type="number"
          min={0.01}
          step="0.01"
          placeholder="49.00"
          defaultValue={defaults ? (defaults.amountCents ?? 0) / 100 : undefined}
          required
        />
      </div>
      <div>
        <label className="label">Category</label>
        <select className="input" name="category" defaultValue={defaults?.category ?? "OTHER"}>
          {EXPENSE_CATEGORIES.map((c) => (
            <option key={c} value={c}>
              {EXPENSE_CATEGORY_LABELS[c as ExpenseCategory]}
            </option>
          ))}
        </select>
      </div>
      <div>
        <label className="label">Vendor</label>
        <input className="input" name="vendor" placeholder="e.g. OVH, Stripe" maxLength={120} defaultValue={defaults?.vendor ?? ""} />
      </div>
      <div>
        <label className="label">Date incurred</label>
        <input
          className="input"
          name="occurredAt"
          type="date"
          defaultValue={defaults?.occurredAt ? toDateInputValue(defaults.occurredAt) : undefined}
        />
      </div>
      <div className="sm:col-span-2">
        <label className="label">Notes</label>
        <input className="input" name="notes" placeholder="internal note (optional)" maxLength={2000} defaultValue={defaults?.notes ?? ""} />
      </div>
      <div className="sm:col-span-2 flex flex-wrap items-center gap-4 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
        <label className="flex items-center gap-2 text-sm">
          <input
            type="checkbox"
            name="isRecurring"
            checked={isRecurring}
            onChange={(e) => setIsRecurring(e.target.checked)}
          />
          Recurring expense
        </label>
        {isRecurring && (
          <>
            <div>
              <select className="input py-1 text-sm" name="recurringInterval" defaultValue={defaults?.recurringInterval ?? "MONTHLY"}>
                {EXPENSE_INTERVALS.map((i) => (
                  <option key={i} value={i}>
                    {i === "MONTHLY" ? "Every month" : "Every year"}
                  </option>
                ))}
              </select>
            </div>
            <div className="flex items-center gap-2 text-xs text-slate-400">
              Next due
              <input
                className="input py-1 text-sm"
                name="nextDueAt"
                type="date"
                defaultValue={defaults?.nextDueAt ? toDateInputValue(defaults.nextDueAt) : undefined}
              />
            </div>
          </>
        )}
      </div>
    </>
  );
}

export function ExpenseCreateForm() {
  const [state, action, pending] = useActionState(createExpense, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state?.ok) formRef.current?.reset();
  }, [state]);

  return (
    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-3">
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Expense added.
        </div>
      )}
      <ExpenseFields />
      <div className="col-span-full">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add expense"}
        </button>
      </div>
    </form>
  );
}

export function ExpenseEditForm({ expense, onDone }: { expense: ExpenseRow; onDone: () => void }) {
  const [state, action, pending] = useActionState(updateExpense, {} as { error?: string; ok?: boolean });

  useEffect(() => {
    if (state?.ok) onDone();
  }, [state, onDone]);

  return (
    <form action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-3">
      <input type="hidden" name="id" value={expense.id} />
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      <ExpenseFields defaults={expense} />
      <div className="col-span-full flex gap-2">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save changes"}
        </button>
        <button type="button" className="btn-ghost" onClick={onDone} disabled={pending}>
          Cancel
        </button>
      </div>
    </form>
  );
}

export function ExpenseRowActions({ expense }: { expense: ExpenseRow }) {
  const [editing, setEditing] = useState(false);
  const [pending, start] = useTransition();

  if (editing) {
    return (
      <tr>
        <td colSpan={7} className="bg-white/[0.02] p-4">
          <ExpenseEditForm expense={expense} onDone={() => setEditing(false)} />
        </td>
      </tr>
    );
  }

  return (
    <div className="flex items-center justify-end gap-1">
      <button className="btn-ghost py-1 text-xs" onClick={() => setEditing(true)}>
        Edit
      </button>
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (confirm(`Delete expense "${expense.description}"?`)) {
            start(() => deleteExpense(expense.id));
          }
        }}
      >
        Delete
      </button>
    </div>
  );
}

/** One expense table row, toggling into an inline edit form. Keeps the
 * row/edit-state logic out of the server-component page. */
export function ExpenseTableRow({
  expense,
  fmtMoney,
  categoryLabel,
}: {
  expense: ExpenseRow;
  fmtMoney: (cents: number) => string;
  categoryLabel: string;
}) {
  const [editing, setEditing] = useState(false);

  if (editing) {
    return (
      <tr>
        <td colSpan={7} className="bg-white/[0.02] p-4">
          <ExpenseEditForm expense={expense} onDone={() => setEditing(false)} />
        </td>
      </tr>
    );
  }

  return (
    <tr>
      <td className="max-w-xs truncate">{expense.description}</td>
      <td className="text-xs text-slate-400">{categoryLabel}</td>
      <td className="text-xs text-slate-400">{expense.vendor ?? "—"}</td>
      <td className="text-right font-mono">{fmtMoney(expense.amountCents)}</td>
      <td className="text-xs text-slate-400">{toDateInputValue(expense.occurredAt)}</td>
      <td className="text-xs text-slate-400">
        {expense.isRecurring ? (expense.recurringInterval === "YEARLY" ? "Yearly" : "Monthly") : "One-off"}
      </td>
      <td className="text-right">
        <div className="flex items-center justify-end gap-1">
