/* Dependency-free SVG charts, safe to render in server components. */

function pathFrom(points: [number, number][], smooth = true): string {
  if (points.length === 0) return "";
  if (!smooth || points.length < 3) {
    return points.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`).join(" ");
  }
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let i = 1; i < points.length; i++) {
    const [x0, y0] = points[i - 1];
    const [x1, y1] = points[i];
    const cx = (x0 + x1) / 2;
    d += ` C${cx.toFixed(2)},${y0.toFixed(2)} ${cx.toFixed(2)},${y1.toFixed(2)} ${x1.toFixed(2)},${y1.toFixed(2)}`;
  }
  return d;
}

function scale(data: number[], w: number, h: number, pad = 2, max?: number): [number, number][] {
  const mx = max ?? Math.max(...data, 1e-9);
  const mn = 0;
  const n = Math.max(data.length - 1, 1);
  return data.map((v, i) => [
    (i / n) * (w - pad * 2) + pad,
    h - pad - ((v - mn) / (mx - mn || 1)) * (h - pad * 2),
  ]);
}

export function Sparkline({
  data,
  width = 120,
  height = 36,
  stroke = "#8a70fb",
  id,
}: {
  data: number[];
  width?: number;
  height?: number;
  stroke?: string;
  id: string;
}) {
  if (data.length === 0) return null;
  const pts = scale(data, width, height);
  const line = pathFrom(pts);
  const area = `${line} L${pts[pts.length - 1][0].toFixed(2)},${height} L${pts[0][0].toFixed(2)},${height} Z`;
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity="0.35" />
          <stop offset="100%" stopColor={stroke} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill={`url(#sg-${id})`} />
      <path d={line} fill="none" stroke={stroke} strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  );
}

