import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { REVENUE_WHERE } from "@/lib/admin-metrics";
import { dedicatedIpPoolMonthlyCostCents } from "@/lib/dedicated-ip";
import { PageHeader, StatCard, Badge, fmtMoney, EmptyState } from "@/components/ui/primitives";
import { AreaChart } from "@/components/ui/charts";
import {
  EXPENSE_CATEGORIES,
  EXPENSE_CATEGORY_LABELS,
  monthKey,
  trailingMonthKeys,
  totalCents,
  totalsByCategory,
  buildTrend,
  projectRecurring,
  totalWithAuto,
  type AutoExpenseLine,
  type ExpenseCategory,
} from "@/lib/accounting";

export const dynamic = "force-dynamic";

const TREND_MONTHS = 6;
const PROJECTION_MONTHS = 3;

export default async function AdminAccounting() {
  await requireArea("accounting");

  const now = new Date();
  const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  const trendStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - (TREND_MONTHS - 1), 1));

  const [revenueThisMonthAgg, invoicedThisMonthAgg, walletRevenueRows, expensesInTrend, recurringExpenses, expenseCount] =
    await Promise.all([
      // Earned revenue = the same REVENUE_WHERE wallet-ledger definition used
      // platform-wide on /admin/billing and /admin/analytics (excludes refunds,
      // affiliate payouts and admin balance corrections — a bare wallet-debit
      // sum double-counts those as income). This is the dashboard's headline
      // "Revenue" figure.
      db.walletTransaction.aggregate({
        where: { ...REVENUE_WHERE, createdAt: { gte: monthStart } },
        _sum: { amountCents: true },
      }),
      // Cross-reference only: PAID invoices dated this month. Invoices are
      // created ALONGSIDE the wallet debit for most orders/renewals, so this is
      // shown separately rather than added to wallet revenue above — summing
      // both would double-count the same sale twice.
      db.invoice.aggregate({
        where: { status: "PAID", paidAt: { gte: monthStart } },
        _sum: { amountCents: true },
      }),
      db.walletTransaction.findMany({
        where: { ...REVENUE_WHERE, createdAt: { gte: trendStart } },
        select: { amountCents: true, createdAt: true },
      }),
      db.expense.findMany({
        where: { occurredAt: { gte: trendStart } },
        select: { amountCents: true, category: true, occurredAt: true, isRecurring: true, recurringInterval: true },
      }),
      db.expense.findMany({
        where: { isRecurring: true },
        select: { amountCents: true, category: true, occurredAt: true, isRecurring: true, recurringInterval: true, description: true },
      }),
      db.expense.count(),
    ]);

  const revenueThisMonthCents = Math.abs(revenueThisMonthAgg._sum.amountCents ?? 0);
  const invoicedThisMonthCents = invoicedThisMonthAgg._sum.amountCents ?? 0;

  // Automatic expense lines pulled from live platform data (no manual entry).
  const ovhIpPoolCents = await dedicatedIpPoolMonthlyCostCents();
  const autoLines: AutoExpenseLine[] = [
    { key: "ovh-ip-pool", label: "OVH dedicated IP pool", amountCents: ovhIpPoolCents, category: "INFRASTRUCTURE" },
  ];

  const manualExpensesThisMonthCents = totalCents(
    expensesInTrend.filter((e) => monthKey(e.occurredAt) === monthKey(now))
  );
  const expensesThisMonthCents = totalWithAuto(manualExpensesThisMonthCents, autoLines);
  const netThisMonthCents = revenueThisMonthCents - expensesThisMonthCents;

  // Trailing months trend (revenue vs expenses vs net).
  const monthKeys = trailingMonthKeys(TREND_MONTHS, now);
  const revenueByMonth = new Map<string, number>();
  for (const k of monthKeys) revenueByMonth.set(k, 0);
  for (const tx of walletRevenueRows) {
    const k = monthKey(tx.createdAt);
    if (revenueByMonth.has(k)) revenueByMonth.set(k, (revenueByMonth.get(k) ?? 0) + Math.abs(tx.amountCents));
  }
  const expensesByMonth = new Map<string, number>();
  for (const k of monthKeys) expensesByMonth.set(k, k === monthKey(now) ? autoLines.reduce((n, l) => n + l.amountCents, 0) : 0);
  for (const e of expensesInTrend) {
    const k = monthKey(e.occurredAt);
    if (expensesByMonth.has(k)) expensesByMonth.set(k, (expensesByMonth.get(k) ?? 0) + e.amountCents);
  }
  const trend = buildTrend(monthKeys, revenueByMonth, expensesByMonth);

  // Category breakdown, this month (manual only — auto lines shown separately below).
  const categoryTotals = totalsByCategory(expensesInTrend.filter((e) => monthKey(e.occurredAt) === monthKey(now)));

  // Recurring expenses projected forward.
  const projected = projectRecurring(recurringExpenses, PROJECTION_MONTHS, now);
  const projectionKeys = trailingMonthKeys(PROJECTION_MONTHS, new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + PROJECTION_MONTHS - 1, 1)));

  return (
    <div className="space-y-6">
      <PageHeader
        title="Accounting"
        sub="Real revenue vs. cost — earned income from the wallet ledger, expenses entered here plus automatic infrastructure costs."
      >
        <Link href="/admin/accounting/expenses" className="btn-primary">
          Manage expenses
        </Link>
      </PageHeader>

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Revenue · this month" value={fmtMoney(revenueThisMonthCents)} delta="wallet ledger, earned only" />
        <StatCard
          label="Expenses · this month"
          value={fmtMoney(expensesThisMonthCents)}
          delta={`incl. ${fmtMoney(ovhIpPoolCents)} auto-pulled`}
        />
        <StatCard
          label="Net · this month"
          value={fmtMoney(netThisMonthCents)}
          delta={netThisMonthCents >= 0 ? "profitable this month" : "running at a loss this month"}
          deltaGood={netThisMonthCents >= 0}
        />
        <StatCard label="Invoiced (paid) · this month" value={fmtMoney(invoicedThisMonthCents)} delta="cross-reference only" />
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <div className="card">
          <h2 className="mb-1 font-semibold">Revenue vs. expenses</h2>
          <p className="mb-3 text-xs text-slate-500">Trailing {TREND_MONTHS} calendar months.</p>
          <AreaChart
            id="acct-trend"
            series={[
              { name: "Revenue $", data: trend.map((t) => t.revenueCents / 100), color: "#34d399" },
              { name: "Expenses $", data: trend.map((t) => t.expenseCents / 100), color: "#f87171" },
            ]}
            height={200}
            yLabel={(v) => `$${v.toFixed(0)}`}
            xLabels={monthKeys.map((k) => k.slice(5))}
          />
        </div>

        <div className="card overflow-x-auto p-0">
          <p className="section-label px-4 pt-4">Monthly net</p>
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Month</th>
                <th className="text-right">Revenue</th>
                <th className="text-right">Expenses</th>
                <th className="text-right">Net</th>
              </tr>
            </thead>
            <tbody>
              {trend.map((t) => (
                <tr key={t.month}>
                  <td>{t.month}</td>
                  <td className="text-right font-mono">{fmtMoney(t.revenueCents)}</td>
                  <td className="text-right font-mono">{fmtMoney(t.expenseCents)}</td>
                  <td className={`text-right font-mono ${t.netCents >= 0 ? "text-emerald-400" : "text-red-400"}`}>
                    {fmtMoney(t.netCents)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <div className="card">
          <h2 className="mb-3 font-semibold">Expenses by category · this month</h2>
          {expenseCount === 0 && ovhIpPoolCents === 0 ? (
            <EmptyState
              title="No expenses yet"
              sub="Add your first expense to start tracking real costs alongside revenue."
              action={
                <Link href="/admin/accounting/expenses" className="btn-primary">
                  Add an expense
                </Link>
              }
            />
          ) : (
            <div className="space-y-2">
              {(EXPENSE_CATEGORIES as readonly ExpenseCategory[]).map((c) => {
                const cents = categoryTotals[c] + (c === "INFRASTRUCTURE" ? ovhIpPoolCents : 0);
                if (cents === 0) return null;
                return (
                  <div key={c} className="flex items-center justify-between border-b border-white/[0.04] py-1.5 text-sm last:border-0">
                    <span className="text-slate-300">{EXPENSE_CATEGORY_LABELS[c]}</span>
                    <span className="font-mono">{fmtMoney(cents)}</span>
                  </div>
                );
              })}
            </div>
          )}
          <p className="mt-3 text-[11px] text-slate-500">
            "Infrastructure" includes the auto-pulled OVH dedicated-IP pool cost ({fmtMoney(ovhIpPoolCents)}/mo across every pooled IP —
            see <Link href="/admin/ips" className="text-brand-300 hover:underline">IP pool</Link>).
          </p>
        </div>

        <div className="card overflow-x-auto p-0">
          <p className="section-label px-4 pt-4">Projected recurring expenses</p>
          <p className="px-4 text-xs text-slate-500">
            Next {PROJECTION_MONTHS} months, from expenses marked recurring. Does not include one-off costs or the auto-pulled OVH line.
          </p>
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Month</th>
                <th className="text-right">Projected</th>
              </tr>
            </thead>
            <tbody>
              {projectionKeys.length === 0 ? (
                <tr>
                  <td colSpan={2} className="py-6 text-center text-slate-500">
                    No recurring expenses yet.
                  </td>
                </tr>
              ) : (
                projectionKeys.map((k) => (
                  <tr key={k}>
                    <td>{k}</td>
                    <td className="text-right font-mono">{fmtMoney(projected.get(k) ?? 0)}</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
          {recurringExpenses.length === 0 && (
            <p className="px-4 pb-4 text-xs text-slate-500">
              Mark an expense as recurring on the{" "}
              <Link href="/admin/accounting/expenses" className="text-brand-300 hover:underline">
                Expenses
              </Link>{" "}
              page to see it projected here.
            </p>
          )}
        </div>
      </div>

      {expenseCount === 0 && (
        <div className="card border-amber-500/20">
          <Badge tone="amber">v1 — foundational</Badge>
          <p className="mt-2 text-sm text-slate-400">
            This is the first pass at real business accounting: expense tracking plus revenue already computed from live
            billing data. No costs are fabricated — every figure above is either an expense you enter yourself or
            pulled automatically from data this platform already tracks (currently just the OVH IP pool). If there's
            a real recurring platform cost you know of (e.g. the OVH server rental itself) that isn't reflected
            anywhere in the system yet, add it as a recurring expense below rather than waiting for it to be
            auto-detected.
          </p>
        </div>
      )}
    </div>
  );
}

