import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { dedicatedIpPoolMonthlyCostCents } from "@/lib/dedicated-ip";
import { PageHeader, fmtMoney } from "@/components/ui/primitives";
import { ExpenseCreateForm, ExpenseTableRow } from "@/components/admin/AccountingControls";
import { EXPENSE_CATEGORIES, EXPENSE_CATEGORY_LABELS, isExpenseCategory, type ExpenseCategory } from "@/lib/accounting";

export const dynamic = "force-dynamic";

export default async function AdminAccountingExpenses({
  searchParams,
}: {
  searchParams: Promise<{ category?: string; from?: string; to?: string }>;
}) {
  await requireArea("accounting");
  const sp = await searchParams;
  const category = sp.category && isExpenseCategory(sp.category) ? sp.category : undefined;
  const from = sp.from ? new Date(sp.from) : undefined;
  const to = sp.to ? new Date(sp.to) : undefined;

  const [expenses, ovhIpPoolCents] = await Promise.all([
    db.expense.findMany({
      where: {
        ...(category ? { category } : {}),
        ...(from || to
          ? {
              occurredAt: {
                ...(from && !Number.isNaN(from.getTime()) ? { gte: from } : {}),
                ...(to && !Number.isNaN(to.getTime()) ? { lte: to } : {}),
              },
            }
          : {}),
      },
      orderBy: { occurredAt: "desc" },
      take: 500,
    }),
    dedicatedIpPoolMonthlyCostCents(),
  ]);

  const filterHref = (params: Record<string, string | undefined>) => {
    const usp = new URLSearchParams();
    const merged = { category: sp.category, from: sp.from, to: sp.to, ...params };
    for (const [k, v] of Object.entries(merged)) if (v) usp.set(k, v);
    const qs = usp.toString();
    return qs ? `/admin/accounting/expenses?${qs}` : "/admin/accounting/expenses";
  };

  const chip = (label: string, active: boolean, href: string) => (
    <Link
      href={href}
      className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
        active
          ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
          : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
      }`}
    >
      {label}
    </Link>
  );

  const totalCents = expenses.reduce((n, e) => n + e.amountCents, 0);

  return (
    <div className="space-y-6">
      <PageHeader title="Expenses" sub="Manually-entered business costs. Add, edit, delete, and filter by category or date.">
        <Link href="/admin/accounting" className="btn-ghost">
          Back to overview
        </Link>
      </PageHeader>

      <div className="card">
        <p className="section-label mb-4">Add an expense</p>
        <ExpenseCreateForm />
      </div>

      <div className="card border-white/[0.06] bg-white/[0.02]">
        <p className="text-xs text-slate-400">
          The OVH dedicated-IP pool cost (<span className="font-mono text-slate-300">{fmtMoney(ovhIpPoolCents)}/mo</span>) is pulled
          in automatically on the{" "}
          <Link href="/admin/accounting" className="text-brand-300 hover:underline">
            overview
          </Link>{" "}
          and is not listed below — it isn't a row in this table, so it can't be edited or deleted here. Manage the pool itself on the{" "}
          <Link href="/admin/ips" className="text-brand-300 hover:underline">
            IP pool
          </Link>{" "}
          page.
        </p>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        {chip("All categories", !category, filterHref({ category: undefined }))}
        {(EXPENSE_CATEGORIES as readonly ExpenseCategory[]).map((c) =>
          chip(EXPENSE_CATEGORY_LABELS[c], category === c, filterHref({ category: c }))
        )}
      </div>

      <form method="GET" className="flex flex-wrap items-end gap-3">
        {category && <input type="hidden" name="category" value={category} />}
        <div>
          <label className="label">From</label>
          <input className="input py-1.5" type="date" name="from" defaultValue={sp.from ?? ""} />
        </div>
        <div>
          <label className="label">To</label>
          <input className="input py-1.5" type="date" name="to" defaultValue={sp.to ?? ""} />
        </div>
        <button className="btn-ghost">Apply date range</button>
        {(sp.from || sp.to) && (
          <Link href={filterHref({ from: undefined, to: undefined })} className="text-xs text-slate-500 hover:text-slate-300">
            Clear dates
          </Link>
        )}
      </form>

      <div className="card overflow-x-auto p-0">
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">
            {expenses.length} expense{expenses.length === 1 ? "" : "s"}
          </p>
          <p className="text-sm font-mono text-slate-300">{fmtMoney(totalCents)} total</p>
        </div>
        {expenses.length === 0 ? (
          <p className="px-4 py-10 text-center text-sm text-slate-400">
            No expenses match these filters yet — add one above, or clear the filters.
          </p>
        ) : (
          <table className="table-shell mt-2 min-w-[900px]">
            <thead>
              <tr>
                <th>Description</th>
                <th>Category</th>
                <th>Vendor</th>
                <th className="text-right">Amount</th>
                <th>Date</th>
                <th>Recurrence</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {expenses.map((e) => (
                <ExpenseTableRow
                  key={e.id}
                  expense={{
                    id: e.id,
                    description: e.description,
                    amountCents: e.amountCents,
                    category: e.category,
                    vendor: e.vendor,
                    notes: e.notes,
                    occurredAt: e.occurredAt.toISOString(),
                    isRecurring: e.isRecurring,
                    recurringInterval: e.recurringInterval,
                    nextDueAt: e.nextDueAt ? e.nextDueAt.toISOString() : null,
                  }}
                  fmtMoney={fmtMoney}
                  categoryLabel={isExpenseCategory(e.category) ? EXPENSE_CATEGORY_LABELS[e.category] : e.category}
                />
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

